/**
 * Extract the root domain from a URL string.
 * Returns "" for non-http(s) URLs or on parse failure.
 */
function extractDomain(url) {
  if (!url) return "";
  try {
    const { hostname } = new URL(url);
    // Strip leading "www."
    return hostname.replace(/^www\./, "");
  } catch (_) {
